def compute(vars):
    old_salary = vars["v1"]
    new_salary = vars["v2"]
    if old_salary == 0:
        return None

    salary_change = new_salary - old_salary
    percentage_increase = salary_change / old_salary * 100

    return {
        "value": percentage_increase,
        "trace": {
            "old_salary": old_salary,
            "new_salary": new_salary,
            "salary_change": salary_change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
